#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <utime.h>
#include <unistd.h>
#include <sys/stat.h>

#define FILENAME "temp_time_test.txt"

void display_times(const char *filename) {
    struct stat st;
    if (stat(filename, &st) == 0) {
        printf("  Access Time (atime): %ld\n", (long)st.st_atime);
        printf("  Modified Time (mtime): %ld\n", (long)st.st_mtime);
    }
}

int main() {
    // 1. Create a dummy file
    FILE *f = fopen(FILENAME, "w");
    if (f == NULL) { perror("fopen"); return EXIT_FAILURE; }
    fclose(f);
    printf("Initial Times:\n");
    display_times(FILENAME);

    // 2. Define a specific time (e.g., Jan 1, 2020)
    time_t past_time = 1577836800; 
    struct utimbuf new_times;
    new_times.actime = past_time + 3600; // Access time set 1 hr later
    new_times.modtime = past_time;       // Modification time set to specific time

    // 3. Call utime() to set specific times
    if (utime(FILENAME, &new_times) == -1) {
        perror("utime specific failed");
        unlink(FILENAME);
        return EXIT_FAILURE;
    }
    printf(
\nTimes set using utimbuf:\n");
    display_times(FILENAME);

    // 4. Call utime() with NULL to set times to current system time
    sleep(1); 
    if (utime(FILENAME, NULL) == -1) {
        perror("utime NULL failed");
        unlink(FILENAME);
        return EXIT_FAILURE;
    }
    printf(
\nTimes set to current system time:\n");
    display_times(FILENAME);

    unlink(FILENAME);
    return EXIT_SUCCESS;
}
